import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.DncwoWA8.js";const i="/projects/ai-skills/diagrams/scaffold-without-implementation.svg",u=JSON.parse('{"title":"Create a skeleton and stop","description":"","frontmatter":{"title":"Create a skeleton and stop"},"headers":[],"relativePath":"workflows/scaffold-without-implementation.md","filePath":"workflows/scaffold-without-implementation.md"}'),r={name:"workflows/scaffold-without-implementation.md"};function l(n,e,d,c,h,p){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="create-a-skeleton-and-stop" tabindex="-1">Create a skeleton and stop <a class="header-anchor" href="#create-a-skeleton-and-stop" aria-label="Permalink to &quot;Create a skeleton and stop&quot;">​</a></h1><p>This is a focused procedure. For its place in a larger workflow, see <a href="/projects/ai-skills/workflows/implement-a-task.html">Implement a planned task</a>.</p><p>A feature&#39;s source structure needs review before behavioral implementation.</p><p><strong>Finish with:</strong> A checked skeleton with explicit fail-fast placeholders.</p><h2 id="read-the-diagram" tabindex="-1">Read the diagram <a class="header-anchor" href="#read-the-diagram" aria-label="Permalink to &quot;Read the diagram&quot;">​</a></h2><p><img src="'+i+'" alt="Create a skeleton and stop: suggested skill handoffs with approval stops where applicable."></p><p><a href="/projects/ai-skills/diagrams/scaffold-without-implementation.html" class="vp-raw">Open interactive diagram</a> · <a href="/projects/ai-skills/diagrams/scaffold-without-implementation.svg">Download SVG</a> · <a href="/projects/ai-skills/diagram-sources/scaffold-without-implementation.json">Editable candidate</a></p><p>Arrows show this suggested sequence, not declared <code>requires</code> dependencies. Approval arrows are conditional. Declining a gate stops that branch without authorizing its writes. The numbered steps below are the text equivalent of the diagram.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><p>Use a trusted project and follow its instructions. Confirm the requested scope, installed skills, runtime tools, and any required workspace or approval. This selection includes the catalogued instruction requirements <a href="/projects/ai-skills/skills/coding.html"><code>coding</code></a>. Resolve them before use.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><strong>Create task branch.</strong> <a href="/projects/ai-skills/skills/isolated-workspace.html"><code>isolated-workspace</code></a> provides the guidance for this step.</li><li><strong>Select language references.</strong> <a href="/projects/ai-skills/skills/coding-with-rules.html"><code>coding-with-rules</code></a> provides the guidance for this step.</li><li><strong>Write source skeletons.</strong> <a href="/projects/ai-skills/skills/scaffold.html"><code>scaffold</code></a> provides the guidance for this step.</li><li><strong>Check structure and stop.</strong> <a href="/projects/ai-skills/skills/scaffold.html"><code>scaffold</code></a> provides the guidance for this step.</li></ol><h2 id="where-to-stop" tabindex="-1">Where to stop <a class="header-anchor" href="#where-to-stop" aria-label="Permalink to &quot;Where to stop&quot;">​</a></h2><p>Do not implement the placeholders. Any later coding or TDD phase needs its own agreed scope and authority.</p><h2 id="optional-branches" tabindex="-1">Optional branches <a class="header-anchor" href="#optional-branches" aria-label="Permalink to &quot;Optional branches&quot;">​</a></h2><ul><li>Choose <a href="/projects/ai-skills/skills/plan-tasks.html"><code>plan-tasks</code></a> when the scope or specification is clear enough to divide into bounded pieces of work.</li><li>Choose <a href="/projects/ai-skills/skills/tdd.html"><code>tdd</code></a> when you explicitly want test-first feature or bug work, or integration-test slices through public behavior.</li></ul><p>Optional branches are not prerequisites or permission to launch another phase. You can omit them or stop at the stated result. See <a href="/projects/ai-skills/reference/relationships.html">relationship types</a> for the distinction.</p>',17)])])}const m=t(r,[["render",l]]);export{u as __pageData,m as default};
